// Extract and structure the submission data
const input = $input.first().json;

const data = {
  path: input.path || 'franchisee',
  brandName: input.brandName || 'Unknown Brand',
  firstName: input.firstName || '',
  lastName: input.lastName || '',
  email: input.email || '',
  phone: input.phone || '',
  linkedIn: input.linkedIn || '',
  numberOfOpenings: input.numberOfOpenings || 0,
  populationDensity: input.populationDensity || 'suburban',
  monthlyAdSpend: input.monthlyAdSpend || 0,
  popupLeadsPerMonth: input.popupLeadsPerMonth || 0,
  b2bEventsPerMonth: input.b2bEventsPerMonth || 0,
  expectedCloseRate: input.expectedCloseRate || 0,
  avgMemberValue: input.avgMemberValue || 0,
  memberLifetimeMonths: input.memberLifetimeMonths || 0,
  monthlyRent: input.monthlyRent || 0,
  monthlyPayroll: input.monthlyPayroll || 0,
  monthlyOtherCosts: input.monthlyOtherCosts || 0,
};

// Results from the frontend calculation
const results = input.results || {};

return [{ json: { ...data, results } }];

// Merge research results and build the report
const submission = $('Parse Submission Data').first().json;
const brandResearch = $('Research: Brand (Google)').first().json;
const prospectResearch = $('Research: Prospect (Google)').first().json;

const r = submission.results || {};
const healthLabel = {
  critical: 'CRITICAL RISK',
  at_risk: 'AT RISK',
  healthy: 'HEALTHY',
  thriving: 'THRIVING'
};

// Extract snippets from Google results (basic text extraction)
function extractSnippets(html) {
  if (!html || typeof html !== 'string') return 'No additional research data available.';
  // Simple extraction of visible text snippets
  const stripped = html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').substring(0, 2000);
  return stripped || 'No additional research data available.';
}

const brandInfo = extractSnippets(typeof brandResearch === 'string' ? brandResearch : brandResearch?.data);
const prospectInfo = extractSnippets(typeof prospectResearch === 'string' ? prospectResearch : prospectResearch?.data);

const costPerLocation = (submission.monthlyRent || 0) + (submission.monthlyPayroll || 0) + (submission.monthlyOtherCosts || 0);

// Build HTML for PDF
const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Helvetica Neue', Arial, sans-serif; color: #1a1a1a; max-width: 800px; margin: 0 auto; padding: 40px; }
    .header { background: #0a0a0a; color: white; padding: 30px; border-radius: 12px; margin-bottom: 30px; }
    .header h1 { margin: 0; color: #10E29C; font-size: 28px; }
    .header p { margin: 8px 0 0; color: #999; }
    .score-banner { padding: 20px; border-radius: 8px; text-align: center; margin-bottom: 24px; }
    .score-critical, .score-at_risk { background: #fef2f2; border: 2px solid #ef4444; }
    .score-healthy, .score-thriving { background: #f0fdf4; border: 2px solid #10E29C; }
    .score-label { font-size: 24px; font-weight: bold; }
    .metrics-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 24px; }
    .metric-card { background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 8px; padding: 16px; }
    .metric-card .label { font-size: 12px; color: #6b7280; text-transform: uppercase; letter-spacing: 0.5px; }
    .metric-card .value { font-size: 24px; font-weight: bold; margin-top: 4px; }
    .section { margin-bottom: 24px; }
    .section h2 { font-size: 18px; border-bottom: 2px solid #10E29C; padding-bottom: 8px; margin-bottom: 16px; }
    table { width: 100%; border-collapse: collapse; }
    td { padding: 8px 12px; border-bottom: 1px solid #e5e7eb; }
    td:last-child { text-align: right; font-weight: 600; }
    .research-box { background: #f3f4f6; border-radius: 8px; padding: 16px; font-size: 13px; line-height: 1.6; max-height: 200px; overflow: hidden; }
    .cta { background: #10E29C; color: #000; padding: 20px; border-radius: 8px; text-align: center; margin-top: 30px; }
    .cta a { color: #000; font-weight: bold; font-size: 18px; text-decoration: none; }
    .footer { text-align: center; margin-top: 30px; color: #9ca3af; font-size: 12px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>Launch Stress Test Report</h1>
    <p>${submission.brandName} &bull; ${submission.firstName} ${submission.lastName} &bull; ${submission.path === 'franchisor' ? 'Franchisor' : 'Franchisee (5+ units)'}</p>
  </div>

  <div class="score-banner score-${r.healthScore || 'at_risk'}">
    <div class="score-label">${healthLabel[r.healthScore] || 'AT RISK'}</div>
    <p>Projected ${r.projectedMembersAtLaunch || 0} members per location &bull; Threshold: 150</p>
  </div>

  <div class="metrics-grid">
    <div class="metric-card">
      <div class="label">Projected Members / Location</div>
      <div class="value">${r.projectedMembersAtLaunch || 0}</div>
    </div>
    <div class="metric-card">
      <div class="label">Total MRR (${submission.numberOfOpenings} locations)</div>
      <div class="value">$${(r.totalMRR || 0).toLocaleString()}</div>
    </div>
    <div class="metric-card">
      <div class="label">Net / Location / Month</div>
      <div class="value" style="color: ${(r.netMonthlyPerLocation || 0) >= 0 ? '#10E29C' : '#ef4444'}">${(r.netMonthlyPerLocation || 0) >= 0 ? '+' : ''}$${(r.netMonthlyPerLocation || 0).toLocaleString()}</div>
    </div>
    <div class="metric-card">
      <div class="label">Member LTV</div>
      <div class="value">$${(r.ltv || 0).toLocaleString()}</div>
    </div>
  </div>

  <div class="section">
    <h2>Input Summary</h2>
    <table>
      <tr><td>Openings (12 mo)</td><td>${submission.numberOfOpenings}</td></tr>
      <tr><td>Market Type</td><td>${submission.populationDensity}</td></tr>
      <tr><td>Monthly Ad Spend</td><td>$${(submission.monthlyAdSpend || 0).toLocaleString()}</td></tr>
      <tr><td>Pop-up Events / mo</td><td>${submission.popupLeadsPerMonth}</td></tr>
      <tr><td>B2B Events / mo</td><td>${submission.b2bEventsPerMonth}</td></tr>
      <tr><td>Close Rate</td><td>${submission.expectedCloseRate}%</td></tr>
      <tr><td>Avg Member Value</td><td>$${submission.avgMemberValue}/mo</td></tr>
      <tr><td>Member Lifetime</td><td>${submission.memberLifetimeMonths} months</td></tr>
      <tr><td>Monthly Costs / Location</td><td>$${costPerLocation.toLocaleString()}</td></tr>
    </table>
  </div>

  <div class="section">
    <h2>Lead Pipeline Analysis</h2>
    <table>
      <tr><td>Paid Leads / mo</td><td>${r.paidLeadsPerMonth || 0}</td></tr>
      <tr><td>Organic Leads / mo</td><td>${r.organicLeadsPerMonth || 0}</td></tr>
      <tr><td>Total Leads / mo</td><td>${r.totalLeadsPerMonth || 0}</td></tr>
      <tr><td>Adjusted CPL</td><td>$${r.adjustedCPL || 0}</td></tr>
      <tr><td>ROAS Ratio</td><td>${(r.roasRatio || 0).toFixed(1)}x</td></tr>
    </table>
  </div>

  <div class="section">
    <h2>Brand Research: ${submission.brandName}</h2>
    <div class="research-box">${brandInfo}</div>
  </div>

  <div class="section">
    <h2>Prospect Research: ${submission.firstName} ${submission.lastName}</h2>
    <div class="research-box">${prospectInfo}</div>
  </div>

  <div class="cta">
    <a href="https://calendly.com/revryze/launch-audit">Book a Launch Audit Call &rarr;</a>
    <p style="margin: 8px 0 0; font-size: 14px;">Let's close the gap and hit 170+ members per opening.</p>
  </div>

  <div class="footer">
    <p>Generated by Revryze Launch Stress Test &bull; ${new Date().toLocaleDateString()}</p>
    <p>Contact: ${submission.email} ${submission.phone ? '&bull; ' + submission.phone : ''}</p>
  </div>
</body>
</html>`;

return [{ json: { ...submission, reportHtml: html, brandInfo, prospectInfo } }];
